// Generated by `pnpm nx g @app/generators:action layouts.put`. Requests go through the real router
// with createTestEngine().inject. They fail until createLayoutsPutAction is implemented; do not weaken them.
import { layoutsPut } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createLayoutsPutAction,
  createWorkspaceFakeDeps,
} from '@app/svc-workspace';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () => createLayoutsPutAction(createWorkspaceFakeDeps());
const def = layoutsPut;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('PUT /connections/{cid}/layout', () => {
  it('GP-1 the route runs layouts.put and answers in the shape of the contract', async () => {
    engine = createTestEngine({ actions: [subject()] });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'PUT',
      path: '/connections/c1/layout',
      payload: { layout: { panels: ['explorer'] } },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
  });

  it('GP-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'PUT',
      path: '/connections/c1/layout',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-3 a caller that does not hold workspace.write gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'PUT',
      path: '/connections/c1/layout',
      payload: { layout: { panels: ['explorer'] } },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('GP-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    engine.arm('c1');
    const answer = await engine.inject({
      method: 'PUT',
      path: '/connections/c1/layout',
      payload: { unexpected: true },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-5 a method nothing is bound to on the path is 405, and Allow lists the bound ones', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'PATCH',
      path: '/connections/c1/layout',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('GET, PUT');
  });
});
